<?php
$page_title='จัดการผู้ใช้งาน';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$message=$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);$id=(int)($_POST['user_id']??0);$username=trim((string)($_POST['username']??''));$email=strtolower(trim((string)($_POST['email']??'')));$fullName=trim((string)($_POST['full_name']??''));$phone=trim((string)($_POST['phone']??''));$role=(string)($_POST['role']??'customer');try{if($id<1||!preg_match('/^[A-Za-z][A-Za-z0-9]{2,29}$/',$username)||!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($fullName)<2||!in_array($role,['customer','seller','admin'],true))throw new RuntimeException('ข้อมูลผู้ใช้ไม่ถูกต้อง');if($id===(int)$_SESSION['user_id']&&$role!=='admin')throw new RuntimeException('ไม่สามารถลดสิทธิ์บัญชีผู้ดูแลที่กำลังใช้งานได้');$duplicate=$db->prepare('SELECT id FROM users WHERE (username=? OR email=?) AND id<>? LIMIT 1');$duplicate->execute([$username,$email,$id]);if($duplicate->fetch())throw new RuntimeException('ชื่อผู้ใช้หรืออีเมลซ้ำกับบัญชีอื่น');$before=$db->prepare('SELECT username,email,full_name,phone,role FROM users WHERE id=?');$before->execute([$id]);$old=$before->fetch();if(!$old)throw new RuntimeException('ไม่พบบัญชีผู้ใช้');$verified=strcasecmp($old['email'],$email)===0?null:0;$sql='UPDATE users SET username=?,email=?,full_name=?,phone=?,role=?'.($verified===0?',email_verified_at=NULL,email_verification_token_hash=NULL,email_verification_expires_at=NULL,email_verification_sent_at=NULL':'').' WHERE id=?';$db->prepare($sql)->execute([$username,$email,$fullName,$phone?:null,$role,$id]);auditLog($db,'admin.user.update','user',$id,$old,['username'=>$username,'email'=>$email,'full_name'=>$fullName,'phone'=>$phone,'role'=>$role]);createNotification($db,$id,'security','ข้อมูลบัญชีถูกแก้ไขโดยผู้ดูแล','หากคุณไม่ได้ร้องขอการแก้ไขนี้ กรุณาติดต่อผู้ดูแลระบบทันที',BASE_URL.'profile.php');$message='บันทึกข้อมูลผู้ใช้เรียบร้อย';}catch(Throwable $e){$error=$e->getMessage();}}
$q=trim((string)($_GET['q']??''));$roleFilter=(string)($_GET['role']??'');$where=' WHERE 1=1';$params=[];if($q!==''){$where.=' AND (username LIKE ? OR email LIKE ? OR full_name LIKE ?)';$params=array_fill(0,3,'%'.$q.'%');}if(in_array($roleFilter,['customer','seller','admin'],true)){$where.=' AND role=?';$params[]=$roleFilter;}$stmt=$db->prepare('SELECT id,username,email,full_name,phone,role,email_verified_at,created_at FROM users'.$where.' ORDER BY id DESC');$stmt->execute($params);$users=$stmt->fetchAll();require_once __DIR__.'/../includes/admin_header.php';
?>
<header class="admin-page-header"><div><p class="eyebrow">USER MANAGEMENT</p><h1>ผู้ใช้งานทั้งหมด</h1><p>ตรวจสอบและแก้ไขชื่อผู้ใช้ อีเมล ข้อมูลติดต่อ และสิทธิ์การใช้งาน</p></div></header><?php if($message):?><div class="admin-alert success"><?php echo e($message);?></div><?php endif;if($error):?><div class="admin-alert error"><?php echo e($error);?></div><?php endif;?>
<section class="admin-panel" style="margin-bottom:18px"><div class="admin-toolbar"><form method="get" class="admin-filter-form"><input type="search" name="q" value="<?php echo e($q);?>" placeholder="ค้นหาชื่อผู้ใช้ อีเมล หรือชื่อจริง"><select name="role"><option value="">ทุกสิทธิ์</option><?php foreach(['customer'=>'ลูกค้า','seller'=>'ผู้ขาย','admin'=>'ผู้ดูแล'] as $key=>$label):?><option value="<?php echo $key;?>" <?php echo $roleFilter===$key?'selected':'';?>><?php echo $label;?></option><?php endforeach;?></select><button class="btn btn-primary">ค้นหา</button></form><span class="result-count"><?php echo count($users);?> บัญชี</span></div></section>
<section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>ID</th><th>บัญชี</th><th>ชื่อและโทรศัพท์</th><th>สิทธิ์</th><th>ยืนยันอีเมล</th><th>จัดการ</th></tr></thead><tbody><?php if(!$users):?><tr><td colspan="6" class="admin-empty">ไม่พบบัญชีผู้ใช้</td></tr><?php endif;foreach($users as $user):$formId='userForm'.(int)$user['id'];?><tr><td>#<?php echo (int)$user['id'];?></td><td><input form="<?php echo $formId;?>" name="username" required maxlength="30" value="<?php echo e($user['username']);?>"><input form="<?php echo $formId;?>" type="email" name="email" required maxlength="100" value="<?php echo e($user['email']);?>"></td><td><input form="<?php echo $formId;?>" name="full_name" required maxlength="100" value="<?php echo e($user['full_name']);?>"><input form="<?php echo $formId;?>" name="phone" maxlength="20" value="<?php echo e($user['phone']);?>"></td><td><select form="<?php echo $formId;?>" name="role"><?php foreach(['customer'=>'ลูกค้า','seller'=>'ผู้ขาย','admin'=>'ผู้ดูแล'] as $key=>$label):?><option value="<?php echo $key;?>" <?php echo $user['role']===$key?'selected':'';?>><?php echo $label;?></option><?php endforeach;?></select></td><td><span class="status-badge <?php echo $user['email_verified_at']?'paid':'pending';?>"><?php echo $user['email_verified_at']?'ยืนยันแล้ว':'ยังไม่ยืนยัน';?></span><small class="cell-subtitle">สมัคร <?php echo e(date('d/m/Y',strtotime($user['created_at'])));?></small></td><td><form id="<?php echo $formId;?>" method="post"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken());?>"><input type="hidden" name="user_id" value="<?php echo (int)$user['id'];?>"><button class="btn btn-primary">บันทึก</button></form></td></tr><?php endforeach;?></tbody></table></div></section>
<?php require_once __DIR__.'/../includes/admin_footer.php';?>
